import {
    Table,
    IntegerColumn,
    TableNameColumn,
    ReferenceColumn,
    DateTimeColumn,
    StringColumn,
    DocumentIdColumn,
    GuidColumn,
} from '@servicenow/sdk/core'

export const incident = Table({
    actions: ['read', 'update', 'create'],
    allowClientScripts: true,
    allowNewFields: true,
    allowUiActions: true,
    allowWebServiceAccess: true,
    attributes: {
        email_client: true,
        hasWorkflow: true,
        live_feed: true,
        'all_tables.query_hints': true,
    },
    audit: true,
    autoNumber: {
        number: 10000,
        prefix: 'INC',
    },
    extends: 'task',
    label: 'Incident',
    licensingConfig: {
        licenseModel: 'fulfiller',
        ownerCondition: 'caller_id=javascript:gs.getUserID()^NQcaller_idISEMPTY^opened_by=javascript:gs.getUserID()^EQ',
    },
    liveFeed: true,
    name: 'incident',
    schema: {
        incident_state: IntegerColumn({
            default: '1',
            dropdown: 'dropdown_without_none',
            dynamicValueDefinitions: {
                type: 'choices_from_other_table',
                table: 'incident',
                field: 'state',
            },
            label: [
                {
                    hint: 'Workflow state of the incident',
                    label: 'Incident state',
                    plural: 'Incident states',
                    language: 'en',
                },
            ],
        }),
        origin_table: TableNameColumn({
            attributes: {
                base_start: true,
            },
            label: [
                {
                    hint: 'Table of the Origin record',
                    label: 'Origin table',
                    plural: 'Origin tables',
                    language: 'en',
                },
            ],
        }),
        caller_id: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                ref_contributions: 'user_show_incidents',
            },
            default: 'javascript:incidentGetCaller();',
            dependent: 'company',
            label: [
                {
                    hint: 'Person who reported or is affected by this incident',
                    label: 'Caller',
                    plural: 'Callers',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_user',
        }),
        reopened_time: DateTimeColumn({
            label: 'Last reopened at',
            readOnly: true,
            readOnlyOption: 'instance_configured',
        }),
        rfc: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'Related change, if one exists',
                    label: 'Change Request',
                    plural: 'Change Requests',
                    language: 'en',
                },
            ],
            referenceTable: 'change_request',
            referenceFloats: true,
        }),
        calendar_stc: IntegerColumn({
            attributes: {
                ignore_filter_on_new: true,
            },
            label: [
                {
                    hint: 'Time elapsed (stored in seconds) before Incident was Resolved',
                    label: 'Resolve time',
                    plural: 'Resolve times',
                    language: 'en',
                },
            ],
            readOnly: true,
            readOnlyOption: 'instance_configured',
        }),
        subcategory: StringColumn({
            dropdown: 'dropdown_with_none',
            dependent: 'category',
            label: 'Subcategory',
        }),
        parent_incident: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'Can be used to collect Incidents for the same root issue',
                    label: 'Parent Incident',
                    plural: 'Parent Incidents',
                    language: 'en',
                },
            ],
            referenceTable: 'incident',
            referenceFloats: true,
            referenceQual: "javascript:'sys_id!='+current.sys_id",
        }),
        resolved_by: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                ignore_filter_on_new: true,
            },
            label: 'Resolved by',
            referenceTable: 'sys_user',
            referenceFloats: true,
        }),
        problem_id: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'Related problem, if one exists',
                    label: 'Problem',
                    plural: 'Problems',
                    language: 'en',
                },
            ],
            referenceTable: 'problem',
            referenceFloats: true,
        }),
        cause: StringColumn({
            label: 'Probable cause',
            maxLength: 4000,
        }),
        close_code: StringColumn({
            dropdown: 'dropdown_with_none',
            label: [
                {
                    hint: 'For use in reporting',
                    label: 'Resolution code',
                    plural: 'Resolution codes',
                    language: 'en',
                },
            ],
        }),
        resolved_at: DateTimeColumn({
            label: 'Resolved',
        }),
        notify: IntegerColumn({
            default: '1',
            dropdown: 'dropdown_without_none',
            label: 'Notify',
        }),
        reopened_by: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                ignore_filter_on_new: true,
            },
            label: 'Last reopened by',
            readOnly: true,
            readOnlyOption: 'instance_configured',
            referenceTable: 'sys_user',
        }),
        caused_by: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'Change request that caused the incident',
                    label: 'Caused by Change',
                    plural: 'Caused by Changes',
                    language: 'en',
                },
            ],
            referenceTable: 'change_request',
        }),
        business_stc: IntegerColumn({
            attributes: {
                ignore_filter_on_new: true,
            },
            label: [
                {
                    hint: 'Business time elapsed (stored in seconds) before Incident was resolved',
                    label: 'Business resolve time',
                    plural: 'Business resolve times',
                    language: 'en',
                },
            ],
            readOnly: true,
            readOnlyOption: 'instance_configured',
        }),
        severity: IntegerColumn({
            default: '3',
            dropdown: 'dropdown_without_none',
            label: 'Severity',
        }),
        category: StringColumn({
            default: 'inquiry',
            dropdown: 'dropdown_with_none',
            label: 'Category',
        }),
        origin_id: DocumentIdColumn({
            dependent: 'origin_table',
            label: 'Origin',
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        business_impact: StringColumn({
            label: 'Business impact',
            maxLength: 4000,
        }),
        hold_reason: IntegerColumn({
            dropdown: 'dropdown_with_none',
            label: 'On hold reason',
        }),
        child_incidents: IntegerColumn({
            default: '0',
            label: [
                {
                    hint: 'Number of child Incidents related to this Problem',
                    label: 'Child Incidents',
                    plural: 'Child Incidents',
                    language: 'en',
                },
            ],
        }),
        reopen_count: IntegerColumn({
            default: '0',
            label: [
                {
                    hint: 'Number of times Incident state has changed from Resolved or Closed to another state',
                    label: 'Reopen count',
                    plural: 'Reopen counts',
                    language: 'en',
                },
            ],
        }),
    },
    textIndex: true,
})
